.processEnv\n  }\n\n  DotenvModule.populate(processEnv, parsed, options)\n\n  return { parsed }\n}\n\nfunction configDotenv (options) {\n  const dotenvPath = path.resolve(process.cwd(), '.env')\n  let encoding = 'utf8'\n  let processEnv = process.env\n  if (options && options.processEnv != null) {\n    processEnv = options.processEnv\n  }\n  let debug = parseBoolean(processEnv.DOTENV_CONFIG_DEBUG || (options && options.debug))\n  let quiet = parseBoolean(processEnv.DOTENV_CONFIG_QUIET || (options && options.quiet))\n\n  if (options && options.encoding) {\n    encoding = options.encoding\n  } else {\n    if (debug) {\n      _debug('no encoding is specified (UTF-8 is used by default)')\n    }\n  }\n\n  let optionPaths = [dotenvPath] // default, look for .env\n  if (options && options.path) {\n    if (!Array.isArray(options.path)) {\n      optionPaths = [_resolveHome(options.path)]\n    } else {\n      optionPaths = [] // reset default\n      for (const filepath of options.path) {\n        optionPaths.push(_resolveHome(filepath))\n      }\n    }\n  }\n\n  // Build the parsed data in a temporary object (because we need to return it).  Once we have the final\n  // parsed data, we will combine it with process.env (or options.processEnv if provided).\n  let lastError\n  const parsedAll = {}\n  for (const path of optionPaths) {\n    try {\n      // Specifying an encoding returns a string instead of a buffer\n      const parsed = DotenvModule.parse(fs.readFileSync(path, { encoding }))\n\n      DotenvModule.populate(parsedAll, parsed, options)\n    } catch (e) {\n      if (debug) {\n        _debug(`failed to load ${path} ${e.message}`)\n      }\n      lastError = e\n    }\n  }\n\n  const populated = DotenvModule.populate(processEnv, parsedAll, options)\n\n  // handle user settings DOTENV_CONFIG_ options inside .env file(s)\n  debug = parseBoolean(processEnv.DOTENV_CONFIG_DEBUG || debug)\n  quiet = parseBoolean(processEnv.DOTENV_CONFIG_QUIET || quiet)\n\n  if (debug || !quiet) {\n    const keysCount = Object.keys(populated).length\n    const shortPaths = []\n    for (const filePath of optionPaths) {\n      try {\n        const relative = path.relative(process.cwd(), filePath)\n        shortPaths.push(relative)\n      } catch (e) {\n        if (debug) {\n          _debug(`failed to load ${filePath} ${e.message}`)\n        }\n        lastError = e\n      }\n    }\n\n    _log(`injected env (${keysCount}) from ${shortPaths.join(',')} ${dim(`// tip: ${_getRandomTip()}`)}`)\n  }\n\n  if (lastError) {\n    return { parsed: parsedAll, error: lastError }\n  } else {\n    return { parsed: parsedAll }\n  }\n}\n\n// Populates process.env from .env file\nfunction config (options) {\n  // fallback to original dotenv if DOTENV_KEY is not set\n  if (_dotenvKey(options).length === 0) {\n    return DotenvModule.configDotenv(options)\n  }\n\n  const vaultPath = _vaultPath(options)\n\n  // dotenvKey exists but .env.vault file does not exist\n  if (!vaultPath) {\n    _warn(`you set DOTENV_KEY but you are missing a .env.vault file at ${vaultPath}`)\n\n    return DotenvModule.configDotenv(options)\n  }\n\n  return DotenvModule._configVault(options)\n}\n\nfunction decrypt (encrypted, keyStr) {\n  const key = Buffer.from(keyStr.slice(-64), 'hex')\n  let ciphertext = Buffer.from(encrypted, 'base64')\n\n  const nonce = ciphertext.subarray(0, 12)\n  const authTag = ciphertext.subarray(-16)\n  ciphertext = ciphertext.subarray(12, -16)\n\n  try {\n    const aesgcm = crypto.createDecipheriv('aes-256-gcm', key, nonce)\n    aesgcm.setAuthTag(authTag)\n    return `${aesgcm.update(ciphertext)}${aesgcm.final()}`\n  } catch (error) {\n    const isRange = error instanceof RangeError\n    const invalidKeyLength = error.message === 'Invalid key length'\n    const decryptionFailed = error.message === 'Unsupported state or unable to authenticate data'\n\n    if (isRange || invalidKeyLength) {\n      const err = new Error('INVALID_DOTENV_KEY: It must be 64 characters long (or more)')\n      err.code = 'INVALID_DOTENV_KEY'\n      throw err\n    } else if (decryptionFailed) {\n      const err = new Error('DECRYPTION_FAILED: Please check your DOTENV_KEY')\n      err.code = 'DECRYPTION_FAILED'\n      throw err\n    } else {\n      throw error\n    }\n  }\n}\n\n// Populate process.env with parsed values\nfunction populate (processEnv, parsed, options = {}) {\n  const debug = Boolean(options && options.debug)\n  const override = Boolean(options && options.override)\n  const populated = {}\n\n  if (typeof parsed !== 'object') {\n    const err = new Error('OBJECT_REQUIRED: Please check the processEnv argument being passed to populate')\n    err.code = 'OBJECT_REQUIRED'\n    throw err\n  }\n\n  // Set process.env\n  for (const key of Object.keys(parsed)) {\n    if (Object.prototype.hasOwnProperty.call(processEnv, key)) {\n      if (override === true) {\n        processEnv[key] = parsed[key]\n        populated[key] = parsed[key]\n      }\n\n      if (debug) {\n        if (override === true) {\n          _debug(`\"${key}\" is already defined and WAS overwritten`)\n        } else {\n          _debug(`\"${key}\" is already defined and was NOT overwritten`)\n        }\n      }\n    } else {\n      processEnv[key] = parsed[key]\n      populated[key] = parsed[key]\n    }\n  }\n\n  return populated\n}\n\nconst DotenvModule = {\n  configDotenv,\n  _configVault,\n  _parseVault,\n  config,\n  decrypt,\n  parse,\n  populate\n}\n\nmodule.exports.configDotenv = DotenvModule.configDotenv\nmodule.exports._configVault = DotenvModule._configVault\nmodule.exports._parseVault = DotenvModule._parseVault\nmodule.exports.config = DotenvModule.config\nmodule.exports.decrypt = DotenvModule.decrypt\nmodule.exports.parse = DotenvModule.parse\nmodule.exports.populate = DotenvModule.populate\n\nmodule.exports = DotenvModule\n", "/**\n * HIKMAT TANI - Cloudflare Worker Entry Point\n * \n * Entry point untuk deployment Cloudflare Workers (Edge Runtime)\n * Berjalan secara paralel dengan server Express Node.js tanpa mengubah\n * atau menggantikan deployment PostgreSQL yang sedang berjalan.\n * \n * Bindings:\n * - env.DB: Cloudflare D1 Database Binding ('hikmat-tani-db')\n * - env.ASSETS: Fetcher untuk static assets dist/ SPA\n */\n\nimport { createD1Client, d1Schema } from './db/d1/index.ts';\nimport { durableOutboxConsumer } from './services/outboxConsumer.ts';\nimport { authService } from './services/authService.ts';\n\nexport interface Env {\n  DB: any; // Cloudflare D1 Database binding\n  ASSETS?: { fetch: (request: Request) => Promise<Response> };\n  DATABASE_PROVIDER?: string;\n  JWT_SECRET?: string;\n  CORS_ORIGIN?: string;\n}\n\nexport default {\n  async fetch(request: Request, env: Env, _ctx: any): Promise<Response> {\n    const url = new URL(request.url);\n\n    // 1. CORS headers\n    const corsHeaders: Record<string, string> = {\n      'Access-Control-Allow-Origin': env.CORS_ORIGIN || '*',\n      'Access-Control-Allow-Methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',\n      'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Requested-With',\n      'X-Content-Type-Options': 'nosniff',\n      'Referrer-Policy': 'strict-origin-when-cross-origin',\n    };\n\n    if (request.method === 'OPTIONS') {\n      return new Response(null, { status: 204, headers: corsHeaders });\n    }\n\n    // 2. Health check endpoints\n    if (url.pathname === '/api/v1/health' || url.pathname === '/api/health') {\n      let d1Status = {\n        configured: Boolean(env.DB),\n        connected: Boolean(env.DB),\n        engine: 'Cloudflare D1 (SQLite Drizzle ORM)',\n        schemaVersion: '1.0.0',\n        tableCount: Object.keys(d1Schema).length,\n      };\n\n      return new Response(\n        JSON.stringify({\n          status: 'ok',\n          app: 'HIKMAT TANI',\n          runtime: 'Cloudflare Workers (Edge)',\n          database: d1Status,\n          timestamp: new Date().toISOString(),\n        }),\n        {\n          status: 200,\n          headers: {\n            'Content-Type': 'application/json',\n            ...corsHeaders,\n          },\n        }\n      );\n    }\n\n    // 3. API D1 Routes placeholder (dapat diperluas bertahap)\n    if (url.pathname.startsWith('/api/')) {\n      if (!env.DB) {\n        return new Response(\n          JSON.stringify({\n            success: false,\n            error: 'Database D1 binding (env.DB) belum terkonfigurasi pada Worker.',\n          }),\n          {\n            status: 503,\n            headers: { 'Content-Type': 'application/json', ...corsHeaders },\n          }\n        );\n      }\n\n      // Inisialisasi Drizzle D1 Client\n      const db = createD1Client(env.DB);\n\n      // Auth Routes: Register\n      if (url.pathname === '/api/v1/auth/register' && request.method === 'POST') {\n        try {\n          const body = (await request.json().catch(() => ({}))) as any;\n          const result = authService.registerFarmer({\n            name: body.name,\n            nik: body.nik,\n            phoneNumber: body.phoneNumber,\n            pin: body.pin,\n            village: body.village,\n            district: body.district,\n            regency: body.regency,\n            province: body.province,\n            farmerGroupName: body.farmerGroupName,\n          });\n\n          return new Response(\n            JSON.stringify({\n              success: true,\n              message: 'Pendaftaran identitas petani berhasil',\n              data: result,\n            }),\n            {\n              status: 201,\n              headers: { 'Content-Type': 'application/json', ...corsHeaders },\n            }\n          );\n        } catch (err: any) {\n          const statusCode = err.statusCode || 400;\n          return new Response(\n            JSON.stringify({\n              success: false,\n              error: {\n                code: err.code || 'REGISTRATION_ERROR',\n                message: err.message || 'Terjadi kesalahan saat pendaftaran',\n              },\n            }),\n            {\n              status: statusCode,\n              headers: { 'Content-Type': 'application/json', ...corsHeaders },\n            }\n          );\n        }\n      }\n\n      // Auth Routes: Login\n      if (url.pathname === '/api/v1/auth/login' && request.method === 'POST') {\n        try {\n          const body = (await request.json().catch(() => ({}))) as any;\n          const cleanIdentifier = body.identifier || body.nik || body.phoneNumber;\n          const result = authService.loginFarmer({\n            identifier: cleanIdentifier,\n            pin: body.pin,\n          });\n\n          return new Response(\n            JSON.stringify({\n              success: true,\n              message: 'Login berhasil',\n              data: result,\n            }),\n            {\n              status: 200,\n              headers: { 'Content-Type': 'application/json', ...corsHeaders },\n            }\n          );\n        } catch (err: any) {\n          const statusCode = err.statusCode || 400;\n          return new Response(\n            JSON.stringify({\n              success: false,\n              error: {\n                code: err.code || 'AUTH_ERROR',\n                message: err.message || 'Login gagal',\n              },\n            }),\n            {\n              status: statusCode,\n              headers: { 'Content-Type': 'application/json', ...corsHeaders },\n            }\n          );\n        }\n      }\n\n      // Auth Routes: Me Profile\n      if (url.pathname === '/api/v1/auth/me' && request.method === 'GET') {\n        const authHeader = request.headers.get('Authorization') || '';\n        const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : null;\n        if (!token) {\n          return new Response(\n            JSON.stringify({\n              success: false,\n              error: { code: 'AUTH_REQUIRED', message: 'Token otentikasi tidak ditemukan' },\n            }),\n            { status: 401, headers: { 'Content-Type': 'application/json', ...corsHeaders } }\n          );\n        }\n        const user = authService.verifyToken(token);\n        if (!user) {\n          return new Response(\n            JSON.stringify({\n              success: false,\n              error: { code: 'INVALID_TOKEN', message: 'Token tidak valid atau kedaluwarsa' },\n            }),\n            { status: 401, headers: { 'Content-Type': 'application/json', ...corsHeaders } }\n          );\n        }\n        const profile = authService.getFarmerProfile(user.farmerId) || {\n          id: user.farmerId,\n          name: user.name || 'Petani Padi Indonesia',\n          nikMasked: '3210********0001',\n          phoneNumber: user.phoneNumber || '081234567890',\n          role: user.role,\n          createdAt: new Date().toISOString(),\n          updatedAt: new Date().toISOString(),\n        };\n\n        return new Response(\n          JSON.stringify({\n            success: true,\n            data: {\n              user: {\n                id: user.userId,\n                role: user.role,\n                isAnonymous: user.isAnonymous,\n              },\n              farmer: profile,\n            },\n          }),\n          { status: 200, headers: { 'Content-Type': 'application/json', ...corsHeaders } }\n        );\n      }\n\n      // Auth Routes: Logout\n      if (url.pathname === '/api/v1/auth/logout' && request.method === 'POST') {\n        return new Response(\n          JSON.stringify({\n            success: true,\n            message: 'Sesi berhasil diakhiri',\n          }),\n          { status: 200, headers: { 'Content-Type': 'application/json', ...corsHeaders } }\n        );\n      }\n\n      // Contoh: Public info config\n      if (url.pathname === '/api/v1/config/public' && request.method === 'GET') {\n        try {\n          const configRecord = await (db as any).select().from(d1Schema.appConfigs).limit(1);\n          return new Response(\n            JSON.stringify({\n              success: true,\n              data: configRecord[0] || null,\n            }),\n            {\n              status: 200,\n              headers: { 'Content-Type': 'application/json', ...corsHeaders },\n            }\n          );\n        } catch (err: any) {\n          return new Response(\n            JSON.stringify({ success: false, error: err.message }),\n            { status: 500, headers: { 'Content-Type': 'application/json', ...corsHeaders } }\n          );\n        }\n      }\n\n      return new Response(\n        JSON.stringify({\n          success: true,\n          message: 'HIKMAT TANI Cloudflare Worker API Ready',\n          path: url.pathname,\n        }),\n        {\n          status: 200,\n          headers: { 'Content-Type': 'application/json', ...corsHeaders },\n        }\n      );\n    }\n\n    // 4. Static assets handling (SPA)\n    if (env.ASSETS) {\n      return env.ASSETS.fetch(request);\n    }\n\n    return new Response('HIKMAT TANI Cloudflare Worker Gateway', {\n      status: 200,\n      headers: { 'Content-Type': 'text/plain', ...corsHeaders },\n    });\n  },\n\n  /**\n   * Cloudflare Cron Trigger Scheduled Handler (Edge Background Execution)\n   * \n   * Dijalankan secara otomatis oleh Cloudflare scheduler untuk memproses\n   * event replikasi outbox PostgreSQL -> D1 tanpa memerlukan request user.\n   */\n  async scheduled(controller: any, env: Env, ctx: any): Promise<void> {\n    const runDrain = async () => {\n      if (!env.DB) {\n        console.warn('[Worker Scheduler] DB binding tidak tersedia untuk drain.');\n        return;\n      }\n\n      try {\n        const db = env.DB?.prepare ? (createD1Client(env.DB)) : env.DB;\n        if (db) {\n          durableOutboxConsumer.setD1Db(db);\n        }\n\n        const workerNodeId = `cf_worker_${controller.cron || 'cron'}_${controller.scheduledTime || Date.now()}`;\n        const result = await durableOutboxConsumer.drainPendingEvents(workerNodeId, 20);\n\n        console.log(`[Worker Scheduler] Outbox drain completed: ${result.completed} completed, ${result.failed} failed, ${result.deadLetter} dead-letter.`);\n      } catch (err: any) {\n        console.error('[Worker Scheduler] Outbox drain error:', err?.message || err);\n      }\n    };\n\n    if (ctx?.waitUntil) {\n      ctx.waitUntil(runDrain());\n    } else {\n      await runDrain();\n    }\n  },\n};\n\n", "import { drizzle, DrizzleD1Database } from 'drizzle-orm/d1';\nimport * as d1Schema from './schema.ts';\n\n/**\n * HIKMAT TANI - Cloudflare D1 Database Adapter & Client Abstraction\n * \n * Modul ini menyediakan adapter ORM Drizzle khusus untuk Cloudflare D1.\n * Didesain 100% kompatibel dengan Cloudflare Workers environment (edge runtime)\n * tanpa ketergantungan pada API khusus Node.js.\n * \n * Jalur Database:\n * 1. Default (Sekarang): PostgreSQL (/server/db/index.ts)\n * 2. Paralel (Migrasi Cloudflare): Cloudflare D1 (/server/db/d1/index.ts)\n */\n\nexport interface D1Database {\n  prepare(query: string): any;\n  dump(): Promise<ArrayBuffer>;\n  batch<T = unknown>(statements: any[]): Promise<any[]>;\n  exec(query: string): Promise<any>;\n}\n\nexport interface D1Status {\n  configured: boolean;\n  connected: boolean;\n  engine: string;\n  schemaVersion: string;\n  tableCount: number;\n}\n\nexport class D1DatabaseService {\n  private static instance: D1DatabaseService;\n  private dbInstance: DrizzleD1Database<typeof d1Schema> | null = null;\n  private isBindingAvailable: boolean = false;\n\n  private constructor(d1Binding?: any) {\n    if (d1Binding) {\n      try {\n        this.dbInstance = drizzle(d1Binding, { schema: d1Schema });\n        this.isBindingAvailable = true;\n      } catch (err) {\n        console.warn('[HIKMAT TANI D1] Peringatan inisialisasi D1 binding:', err);\n      }\n    }\n  }\n\n  public static getInstance(d1Binding?: any): D1DatabaseService {\n    if (!D1DatabaseService.instance || d1Binding) {\n      D1DatabaseService.instance = new D1Datab